for r in range(H):
 for x in range(W):
  col=g[r][x]
  if col in (6,) or (r,x) in seen: continue
  q=[(r,x)]; seen.add((r,x)); pts=[]
  while q:
   a,b=q.pop(); pts.append((a,b))
   for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
    u,v=a+da,b+db
    if 0<=u<H and 0<=v<W and g[u][v]==col and (u,v) not in seen: seen.add((u,v)); q.append((u,v))
  r0=min(a for a,b in pts); c0=min(b for a,b in pts); shape=tuple(sorted((a-r0,b-c0) for a,b in pts)); comps.append((col,len(pts),r0,c0,max(a for a,b in pts),max(b for a,b in pts),shape))
for i,z in enumerate(comps): print(i,'color',z[0],'size',z[1],'box',z[2:6],'shape',z[6]);
groups=collections.defaultdict(list)
for i,z in enumerate(comps): groups[(z[0],z[6])].append(i)
print('DUPLICATES SAME COLOR')
for k,v in groups.items():
 if len(v)>1: print(k[0],v)
print('ALL SHAPE DUPLICATE ACROSS COLORS')
h=collections.defaultdict(list)
for i,z in enumerate(comps): h[z[6]].append(i)
for shape,inds in h.items():
 if len(inds)>1: print('shape size',len(shape),'indices',inds,'colors',[comps[i][0] for i in inds],'boxes',[comps[i][2:6] for i in inds])"'''
